function LadderStruggleMainChallengeCell:OnChallengeBtnClicked()
    -- UIModule.CloseDialog(UIModule.CurrentScreen:LastDialog())
    UIModule.OpenDialog({ id = self.component.UIFormationDialog, parameters = {
        playerInfoList = {
            [1] = nil,
            [2] = self.data or {}
        },
        refreshMyselfPlayerInfo = true,
        systemName = self.systemName,
    } })
