--- 更新cell数据
---@param data any
function LadderStruggleMainChallengeCell:UpdatePlayerInfo(data)
    if isNull(data) then
        return
    end
    -- print("[大乱斗] 挑战按钮", table.dump(data, nil, 5))
    self.data = data
    local rank = checkInt(data.ranking)
    local playerName = data.name
    local avatarId = checkInt(data.avatar)
    local avatarFrameId = checkInt(data.avatarFrame)
    local level = checkInt(data.level)
    local combatValue = data.combatValue
    local isMyself = data.isMyself or false

    KTool.SetActive(self.RT_MyselfIcon, isMyself)
    KTool.SetActive(self.RT_TextMyself, isMyself)
    KTool.SetActive(self.Btn_Challenge, not isMyself)
    self.Txt_Rank.text = tostring(rank)
    self.Txt_PlayerLevel.text = level
    self.Txt_PlayerName.text = playerName
    self.Txt_PlayerCombatValue.text = tostring(combatValue)
    self.LB_PlayerHead.Env:FreshAvatarFrame(avatarId, avatarFrameId)

    KTool.SetActive(self.RT_FirstToThird, rank <= 3)
    KTool.SetActive(self.RT_FourthToFinal, rank > 3)
end

function LadderStruggleMainChallengeCell:GetPlayerId()
    return self.data.playerId
end

function LadderStruggleMainChallengeCell:UpdateCombatValue(value)
    self.data.combatValue = value
    self.Txt_PlayerCombatValue.text = tostring(value)
end

return LadderStruggleMainChallengeCell